            "\u0001\uf3fd\u17a7\u0001\uf3fe\u17a8\u0001\uf3ff\u17a9\u0001\uf3fb\u17ac\u0001\uf3fc\u17ad\u0001\uf3fd\u17ae\u0001\uf3fe\u17af\u0001\uf3ff\u17b0\u0001\uf3fb\u17b2\u0001\uf3fc\u17b3\u0001\uf3fd\u17b4\u0001\uf3fe\u17b5\u0001\uf3ff\u17b6\u0001\uf3fb\u17b8\u0001\uf3fc\u17b9\u0001\uf3fd\u17ba\u0001\uf3fe\u17bb\u0001\uf3ff\u17bc\u0001\uf3fb\u17be\u0001\uf3fc\u17bf\u0001\uf3fd\u17c0\u0001\uf3fe\u17c1\u0001\uf3ff\u17c2\u0001\uf3fb\u17c4\u0001\uf3fc\u17c5\u0001\uf3fd\u17c6\u0001\uf3fe" +
            "\u17c7\u0001\uf3ff\u17c8\u0001\uf3fb\u17cb\u0001\uf3fc\u17cc\u0001\uf3fd\u17cd\u0001\uf3fe\u17ce\u0001\uf3ff\u17cf\u0001\uf3fb\u17d1\u0001\uf3fc\u17d2\u0001\uf3fd\u17d3\u0001\uf3fe\u17d4\u0001\uf3ff\u17d5\u0001\uf3fb\u17d7\u0001\uf3fc\u17d8\u0001\uf3fd\u17d9\u0001\uf3fe\u17da\u0001\uf3ff\u17db\u0001\uf3fb\u17dd\u0001\uf3fc\u17de\u0001\uf3fd\u17df\u0001\uf3fe\u17e0\u0001\uf3ff\u17e1\u0001\uf3fb\u17e3\u0001\uf3fc\u17e4\u0001\uf3fd\u17e5\u0001\uf3fe\u17e6\u0001\uf3ff\u17e7\u0001" +
            "\uf4a5\u17e9\u0000\u26a7\u17f8\u0001\uf308\u17f7\u0000\ufe0f\u17f9";

        private static int Scalar(string data, int p) { return data[p] * 65536 + data[p + 1]; }
        private static bool InRanges(string data, int scalar)
        {
            int low = 0, high = data.Length / 4 - 1;
            while (low <= high)
            {
                int mid = low + (high - low) / 2, p = mid * 4;
                if (scalar < Scalar(data, p)) high = mid - 1;
                else if (scalar > Scalar(data, p + 2)) low = mid + 1;
                else return true;
            }
            return false;
        }
        internal static bool IsEmoji(int scalar) { return InRanges(EmojiRanges, scalar); }
        internal static bool IsPresentation(int scalar) { return InRanges(PresentationRanges, scalar); }
        internal static bool IsModifier(int scalar) { return InRanges(ModifierRanges, scalar); }
        internal static bool IsModifierBase(int scalar) { return InRanges(ModifierBaseRanges, scalar); }
        internal static bool IsExtendedPictographic(int scalar) { return InRanges(ExtendedPictographicRanges, scalar); }
        internal static bool IsExtend(int scalar) { return InRanges(ExtendRanges, scalar); }
        internal static bool IsSpacingMark(int scalar) { return InRanges(SpacingMarkRanges, scalar); }
        internal static bool IsRegional(int scalar) { return InRanges(RegionalRanges, scalar); }
        internal static int SequenceKind(List<int> points, int start, int end)
        {
            int state = 0;
            for (int i = start; i < end; i++)
            {
                int at = state * 3, low = States[at], high = low + States[at + 1] - 1, next = -1;
                while (low <= high)
                {
                    int mid = low + (high - low) / 2, p = mid * 3, scalar = Scalar(Edges, p);
                    if (points[i] < scalar) high = mid - 1;
                    else if (points[i] > scalar) low = mid + 1;
                    else { next = Edges[p + 2]; break; }
                }
                if (next < 0) return 0;
                state = next;
            }
            return States[state * 3 + 2];
        }
    }
